+      :primary-contact="primaryContact"
+      :on-contact-search="onContactSearch"
+      :is-searching="isSearching"
+      :is-merging="uiFlags.isMerging"
+      :search-results="searchResults"
+      @search="onContactSearch"
+      @submit="onMergeContacts"
+    />
